div.script:
  function onpercent_change(value,record){
    var total_percent_value = document.getElementsByClassName("percent")[0].value;
    var total_percent_splited = total_percent_value.split('%');
    var percentage_value = document.getElementsByClassName("percentage_value");
    var percent = 0
    for(var i=0;i < percentage_value.length;i++){
        if(i > 0){
          var splited_percent_value = (percentage_value[i].value).replace(/\%/g,'');
          var trim_percent_value = splited_percent_value.trim();
          var int_percent = parseInt(trim_percent_value);
          percent += int_percent
        }
    }
    var remaining_percent = parseInt(total_percent_splited) - percent
    document.getElementsByClassName("percentage_value")[0].value = String(remaining_percent) +'%';

    var total_subtotal_value = document.getElementsByClassName("subtotal")[0].value;
    var splited_value = value.replace(/\%/g,'');
    var int_value = parseInt(splited_value);
    var total_parent_subtotal = parseInt(total_subtotal_value) * parseInt(int_value) / 100;
    record.parentNode.nextSibling.nextSibling.childNodes[3].value = total_parent_subtotal;
    var parent_percent_value = document.getElementsByClassName("percentage_value")[0].value;
    var parent_percent_splited = parent_percent_value.replace(/\%/g,'');
    var subtotal_parent = parseInt(total_subtotal_value) * parseInt(parent_percent_splited) / 100;

    var subtotalInput = record.parentNode.nextSibling.nextSibling.querySelector("input.subtotal_value");
    if (subtotalInput) {
        subtotalInput.value = total_parent_subtotal;
    }

    var total_taxamount_value = document.getElementsByClassName("taxamountvl")[0].value;
    var total_parent_taxamount = parseInt(total_taxamount_value) * parseInt(int_value) / 100;
    var taxamount_parent = parseInt(total_taxamount_value) * parseInt(parent_percent_splited) / 100;
    var taxAmountInput = record.parentNode.parentNode.querySelector("input.taxamount_value");
    if (taxAmountInput) {
        taxAmountInput.value = total_parent_taxamount;
    }

    document.getElementsByClassName("subtotal_value")[0].value = subtotal_parent;
    document.getElementsByClassName("taxamount_value")[0].value = taxamount_parent;
};


  function onsubtotal_change(value,record){
    var total_percent_value = document.getElementsByClassName("subtotal")[0].value;
    var total_percent_splited = total_percent_value.split('%');
    var subtotal_value = document.getElementsByClassName("subtotal_value");
    var total_subtotal_value = document.getElementsByClassName("subtotal")[0].value;
    var subtotal = 0;

    for(var i=0;i < subtotal_value.length;i++){
        if(i > 0){
          var int_subtotal = parseInt(subtotal_value[i].value);
          subtotal += int_subtotal
        }
    }
    var remaining_subtotal = parseInt(total_subtotal_value) - subtotal;
    document.getElementsByClassName("subtotal_value")[0].value = remaining_subtotal;

    var percent_val = parseInt(value) * 100/ parseInt(total_subtotal_value);
    var round_percent = parseFloat(percent_val).toFixed(2);

    var percentage_input = record.parentNode.nextSibling.parentElement.querySelector("input.percentage_value");
    if (percentage_input) {
        percentage_input.value = String(round_percent) + '%';
    }

    var fst_subtotal = document.getElementsByClassName("subtotal_value")[0].value;
    var fst_percent_val = parseInt(fst_subtotal) * 100/ parseInt(total_subtotal_value);
    var fst_concat_percent = parseFloat(fst_percent_val).toFixed(2);

    document.getElementsByClassName("percentage_value")[0].value = String(fst_concat_percent) + '%';

    var total_taxamount_value = parseInt(document.getElementsByClassName("taxamountvl")[0].value);

    var taxAmountInput = record.parentNode.parentNode.querySelector("input.taxamount_value");
    if (taxAmountInput) {
        var tax_for_row = (total_taxamount_value * percent_val) / 100;
        taxAmountInput.value = tax_for_row.toFixed(1);
    }

    var parent_percent_value = document.getElementsByClassName("percentage_value")[0].value.replace('%', '');
    var taxamount_parent = (total_taxamount_value * parseFloat(parent_percent_value)) / 100;
    document.getElementsByClassName("taxamount_value")[0].value = taxamount_parent.toFixed(1);

    console.log("Tax Amount for Row: ", tax_for_row);
    console.log("Parent Tax Amount: ", taxamount_parent);


















};

  function ontaxamount_change(value,record){
    var total_percent_value = document.getElementsByClassName("taxamountvl")[0].value;
    var total_percent_splited = total_percent_value.split('%');
    var taxamount_value = document.getElementsByClassName("taxamount_value");
    var total_taxamount_value = document.getElementsByClassName("taxamountvl")[0].value;
    var taxamountvl = 0;

    for(var i=0;i < taxamount_value.length;i++){
        if(i > 0){
          var int_taxamount = parseInt(taxamount_value[i].value);
          taxamountvl += int_taxamount
        }
    }
    var remaining_taxamount = parseInt(total_taxamount_value) - taxamountvl;
    document.getElementsByClassName("taxamount_value")[0].value = remaining_taxamount;

    var percent_val = parseInt(value) * 100 / parseInt(total_percent_value);
    var round_percent = parseFloat(percent_val).toFixed(2);

    var percentage_input = record.parentNode.nextSibling.parentElement.querySelector("input.percentage_value");
    if (percentage_input) {
        percentage_input.value = String(round_percent) + '%';
    }

    var fst_taxamount = document.getElementsByClassName("taxamount_value")[0].value;
    var fst_percent_val = parseInt(fst_taxamount) * 100 / parseInt(total_taxamount_value);
    var fst_concat_percent = parseFloat(fst_percent_val).toFixed(2);

    document.getElementsByClassName("percentage_value")[0].value = String(fst_concat_percent) + '%';

    var percent_val = (parseInt(value) / total_taxamount_value) * 100;
    var round_percent = percent_val.toFixed(2);

    var percentage_input = record.parentNode.nextSibling.parentElement.querySelector("input.percentage_value");
    if (percentage_input) {
        percentage_input.value = String(round_percent) + '%';
    }

    var total_subtotal_value = parseInt(document.getElementsByClassName("subtotal")[0].value);
    var subtotal_for_row = (total_subtotal_value * percent_val) / 100;

    var subtotalInput = record.parentNode.parentNode.querySelector("input.subtotal_value");
    if (subtotalInput) {
        subtotalInput.value = subtotal_for_row.toFixed(2);
    }

    var parent_percent_value = document.getElementsByClassName("percentage_value")[0].value.replace('%', '');
    var subtotal_parent = (total_subtotal_value * parseFloat(parent_percent_value)) / 100;

    document.getElementsByClassName("subtotal_value")[0].value = subtotal_parent.toFixed(2);

    console.log("Tax Amount for Row: ", value);
    console.log("Subtotal for Row: ", subtotal_for_row);
    console.log("Parent Subtotal: ", subtotal_parent);



















};
